+        w: rnd() * TAU,
+        emit,
+      });
+    }
+    const dummy = new THREE.Object3D();
+
+    const PLANK = 260;
+    const plankGeo = new THREE.BufferGeometry();
+    const plankPos = new Float32Array(PLANK * 3);
+    for (let i = 0; i < PLANK; i++) {
+      plankPos[i * 3] = rand(-24, 24);
+      plankPos[i * 3 + 1] = rand(0.4, 12);
+      plankPos[i * 3 + 2] = rand(-16, 14);
+    }
+    plankGeo.setAttribute('position', new THREE.BufferAttribute(plankPos, 3));
+    const plank = new THREE.Points(plankGeo, new THREE.PointsMaterial({
+      color: 0xd8fff4,
+      size: 0.055,
+      map: softTex,
+      transparent: true,
+      depthWrite: false,
+      blending: THREE.AdditiveBlending,
+      opacity: 0.75,
+    }));
+    scene.add(plank);
+
+    const composer = new EffectComposer(renderer);
+    composer.renderTarget1.samples = 4;
+    composer.renderTarget2.samples = 4;
+    composer.addPass(new RenderPass(scene, camera));
+    const bloomPass = new UnrealBloomPass(new THREE.Vector2(innerWidth, innerHeight), 0.34, 0.46, 0.9);
+    composer.addPass(bloomPass);
+    const grade = new ShaderPass({
+      uniforms: { tDiffuse: { value: null }, uTime: { value: 0 } },
+      vertexShader: /* glsl */`
+        varying vec2 vUv;
+        void main() {
+          vUv = uv;
+          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
+        }
+      `,
+      fragmentShader: /* glsl */`
+        uniform sampler2D tDiffuse;
+        uniform float uTime;
+        varying vec2 vUv;
+        void main() {
+          vec2 q = vUv - 0.5;
+          vec2 uv = vUv + vec2(sin(vUv.y * 26.0 + uTime * 0.65), cos(vUv.x * 22.0 + uTime * 0.5)) * 0.0011;
+          vec2 off = q * 0.0032;
+          float r = texture2D(tDiffuse, uv + off).r;
+          float gch = texture2D(tDiffuse, uv).g;
+          float b = texture2D(tDiffuse, uv - off).b;
+          vec3 col = vec3(r, gch, b);
+          float l = dot(col, vec3(0.2126, 0.7152, 0.0722));
+          col = mix(vec3(l), col, 1.14);
+          col = mix(vec3(0.02, 0.07, 0.11), col, 0.94);
+          col.b += 0.012;
+          col.g += 0.006;
+          float vig = smoothstep(0.86, 0.28, length(q));
+          col *= mix(0.62, 1.0, vig);
+          gl_FragColor = vec4(col, 1.0);
+        }
+      `,
+    });
+    composer.addPass(grade);
+    composer.addPass(new OutputPass());
+
+    function resize() {
+      camera.aspect = innerWidth / innerHeight;
+      camera.updateProjectionMatrix();
+      renderer.setSize(innerWidth, innerHeight);
+      composer.setSize(innerWidth, innerHeight);
+    }
+    addEventListener('resize', resize);
+
+    const boot = document.getElementById('boot');
+    let last = performance.now();
+    renderer.setAnimationLoop((now) => {
+      const t = now * 0.001;
+      const dt = Math.min(0.05, (now - last) * 0.001);
+      last = now;
+      timeU.value = t;
+      grade.uniforms.uTime.value = t;
+      idle += dt;
+      if (!reduced && idle > 5) controls.autoRotate = true;
+      controls.update();
+
+      sponges.update(t);
+      patrick.update(t);
+      squid.update(t);
+
+      const ga = t * 0.32 * (reduced ? 0.2 : 1);
+      gary.group.position.x = GARY.x + Math.cos(ga) * 0.8;
+      gary.group.position.z = GARY.z + Math.sin(ga) * 0.5;
+      gary.group.position.y = 0.06 + Math.abs(Math.sin(t * 3.1)) * 0.03 * motion;
+      gary.group.rotation.y = -ga + Math.PI / 2;
+      gary.stalks.forEach((s, i) => {
+        s.rotation.z = Math.sin(t * 2.1 + i) * 0.18 * motion;
+        s.rotation.x = Math.cos(t * 1.7 + i) * 0.12 * motion;
+      });
+
+      kelps.forEach((k) => {
+        k.segs.forEach((s, i) => {
+          const amp = (0.018 + i * 0.02) * motion;
+          s.rotation.z = Math.sin(t * 0.9 + k.phase + i * 0.4) * amp;
+          s.rotation.x = Math.cos(t * 0.72 + k.phase + i) * amp * 0.65;
+        });
+      });
+      flowers.forEach((f) => {
+        f.rotation.z = Math.sin(t * 0.8 + f.userData.phase) * 0.08 * motion;
+      });
+      anemones.forEach((a) => {
+        a.fronds.forEach((f, i) => {
+          const wob = Math.sin(t * 1.3 + a.phase + i) * 0.18 * motion;
+          f.rotation.z = Math.cos(f.userData.a) * 0.35 + wob;
+          f.rotation.x = -Math.sin(f.userData.a) * 0.35;
+        });
+      });
+      leafPivots.forEach((p, i) => {
+        p.rotation.x = p.userData.bx + Math.sin(t * 0.8 + i) * 0.035 * motion;
+        p.rotation.z = p.userData.bz + Math.cos(t * 0.7 + i * 0.6) * 0.035 * motion;
+      });
+      smokes.forEach((s) => {
+        s.userData.t = (s.userData.t + dt * 0.16) % 1;
+        const u = s.userData.t;
+        s.position.y = 5.65 + u * 1.55;
+        s.position.x = 1.22 + Math.sin(u * 9 + t) * 0.12;
+        s.scale.setScalar(0.45 + u * 1.5);
+        s.material.opacity = (1 - u) * 0.32;
+      });
+      if (flagPivot.mesh) {
+        flagPivot.mesh.rotation.y = Math.sin(t * 1.6) * 0.45 * motion;
+        flagPivot.mesh.scale.x = 0.85 + Math.sin(t * 3.2) * 0.12 * motion;
+      }
+
+      jellies.forEach((j) => {
+        j.group.position.x = j.base.x + Math.sin(t * 0.18 + j.phase) * 1.15 * motion;
+        j.group.position.y = j.base.y + Math.sin(t * 0.85 + j.phase) * 0.42 * motion;
+        j.group.position.z = j.base.z + Math.cos(t * 0.14 + j.phase) * 0.7 * motion;
+        j.group.rotation.z = Math.sin(t * 0.6 + j.phase) * 0.08 * motion;
+        j.bell.scale.y = j.scale * (0.78 + Math.sin(t * 1.5 + j.phase) * 0.06 * motion);
+        j.strands.forEach((joints, s) => {
+          joints.forEach((pivot, k) => {
+            pivot.rotation.x = Math.sin(t * 1.45 + j.phase + s + k * 0.55) * (0.16 + k * 0.04) * motion;
+            pivot.rotation.z = Math.cos(t * 1.15 + j.phase + k) * 0.1 * motion;
+          });
+        });
+      });
+
+      fish.forEach((f) => {
+        const a = t * f.speed * (reduced ? 0.25 : 1) + f.phase;
+        f.group.position.set(
+          f.center.x + Math.cos(a) * f.radius,
+          f.y + Math.sin(t * 0.8 + f.phase) * 0.25,
+          f.center.z + Math.sin(a) * f.radius * 0.62
+        );
+        f.group.rotation.y = -a + Math.PI / 2;
+        f.tail.rotation.y = Math.sin(t * 7 + f.phase) * 0.45 * motion;
+      });
+
+      for (let i = 0; i < BUBBLES; i++) {
+        const b = bubbles[i];
+        b.y += b.v * dt * (reduced ? 0.35 : 1);
+        b.x += Math.sin(t * 0.8 + b.w) * 0.15 * dt;
+        if (b.y > 14.2) {
+          b.y = 0.15;
+          if (b.emit) {
+            b.x = b.emit[0] + rand(-0.35, 0.35);
+            b.z = b.emit[1] + rand(-0.35, 0.35);
+          } else {
+            b.x = rand(-20, 20);
+            b.z = rand(-12, 10);
+          }
+        }
+        dummy.position.set(b.x, b.y, b.z);
+        dummy.scale.setScalar(b.s * (1 + Math.sin(t * 2 + b.w) * 0.08));
+        dummy.updateMatrix();
+        bubbleMesh.setMatrixAt(i, dummy.matrix);
+      }
+      bubbleMesh.instanceMatrix.needsUpdate = true;
+
+      const attr = plankGeo.attributes.position;
+      for (let i = 0; i < PLANK; i++) {
+        let x = attr.getX(i) + dt * 0.18;
+        let y = attr.getY(i) + Math.sin(t + i) * 0.05 * dt;
+        let z = attr.getZ(i) + dt * 0.05;
+        if (x > 24) x = -24;
+        if (z > 14) z = -16;
+        attr.setXYZ(i, x, y, z);
+      }
+      attr.needsUpdate = true;
+
+      composer.render();
+      if (boot && !boot.dataset.ready) {
+        boot.dataset.ready = '1';
+        boot.classList.add('gone');
+      }
+    });
+  </script>
+</body>
+</html>

