const CAUSTIC_FN = /* glsl */`
  float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 345.45));
    p += dot(p, p + 34.345);
    return fract(p.x * p.y);
  }
  float cellDist(vec2 uv, float t) {
    vec2 i = floor(uv);
    vec2 f = fract(uv);
    float m = 1.0;
    for (int y = -1; y <= 1; y++) {
      for (int x = -1; x <= 1; x++) {
        vec2 g = vec2(float(x), float(y));
        vec2 o = vec2(hash21(i + g), hash21(i + g + 17.3));
        o = 0.5 + 0.5 * sin(t + 6.28318 * o);
        m = min(m, length(g + o - f));
      }
    }
    return m;
  }
  float caustics(vec2 xz, float t) {
    vec2 p = xz * 0.62;
    float s1 = sin(p.x * 1.15 + t * 0.55) * sin(p.y * 1.05 - t * 0.4);
    float s2 = sin((p.x + p.y) * 0.72 + t * 0.7) * sin((p.x - p.y) * 0.66 - t * 0.5);
    float bands = pow(max(s1, 0.0), 2.0) * pow(max(s2, 0.0), 2.0);
    float d = cellDist(xz * 0.38, t * 0.8);
    float ridge = smoothstep(0.02, 0.085, d) * (1.0 - smoothstep(0.085, 0.2, d));
    return clamp(bands * 2.15 + ridge, 0.0, 1.0);
  }
`;

