dev-browser <<'EOF'
const page = await browser.getPage("sponge");
await page.setViewportSize({ width: 1440, height: 900 });
const logs = [];
page.on('console', (msg) => { if (msg.type() === 'error' || msg.type() === 'warning') logs.push(msg.type() + ': ' + msg.text()); });
page.on('pageerror', (err) => logs.push('PAGE: ' + err.message));
await page.goto('http://127.0.0.1:8877/?v=2', { waitUntil: 'domcontentloaded', timeout: 30000 });
await page.waitForSelector('#boot.gone', { timeout: 20000 });
await page.waitForTimeout(1600);
const fps = await page.evaluate(() => new Promise((resolve) => {
  let frames = 0;
  const start = performance.now();
  function loop(t) {
    frames++;
    if (t - start < 1000) requestAnimationFrame(loop);
    else resolve(frames);
  }
  requestAnimationFrame(loop);
}));
const buf = await page.screenshot({ type: 'png' });
const shot = await saveScreenshot(buf, 'sponge-wide.png');
const box = await page.locator('canvas').boundingBox();
await page.mouse.move(box.x + box.width * 0.5, box.y + box.height * 0.55);
await page.mouse.down();
await page.mouse.move(box.x + box.width * 0.5 + 180, box.y + box.height * 0.55 - 40, { steps: 12 });
await page.mouse.up();
await page.waitForTimeout(700);
const buf2 = await page.screenshot({ type: 'png' });
const shot2 = await saveScreenshot(buf2, 'sponge-orbit.png');
await page.mouse.move(box.x + box.width * 0.62, box.y + box.height * 0.48);
await page.mouse.wheel(0, -900);
await page.waitForTimeout(600);
const buf3 = await page.screenshot({ type: 'png' });
const shot3 = await saveScreenshot(buf3, 'sponge-zoom.png');
console.log(JSON.stringify({ fps, shot, shot2, shot3, logs, title: await page.title() }, null, 2));
EOF

