float caustics(vec2 xz, float t) {
  vec2 p = xz * 0.9;
  float s1 = sin(p.x * 1.25 + t * 0.55) * sin(p.y * 1.05 - t * 0.42);
  float s2 = sin((p.x + p.y) * 0.82 + t * 0.75) * sin((p.x - p.y) * 0.7 - t * 0.5);
  float s3 = sin(p.x * 1.8 - p.y * 1.45 + t);
  float d = cellDist(p * 0.55, t * 0.7);
  float weave = pow(max(s1, 0.0), 1.4) * pow(max(s2, 0.0), 1.4);
  weave += pow(max(s3, 0.0), 4.0) * 0.28;
  weave *= 0.55 + 0.45 * smoothstep(0.02, 0.22, d);
  return clamp(weave * 1.35, 0.0, 1.0);
}

