dev-browser --browser sponge-bb <<'EOF'
const page = await browser.getPage("main");
await page.setViewportSize({ width: 1440, height: 900 });
const logs = [];
page.on('pageerror', (err) => logs.push('PAGE: ' + err.message));
page.on('console', (msg) => { if (msg.type() === 'error') logs.push(msg.text()); });
await page.goto('http://127.0.0.1:8877/?v=5', { waitUntil: 'domcontentloaded', timeout: 30000 });
await page.waitForSelector('#boot.gone', { timeout: 20000 });
await page.waitForTimeout(1000);
const fps = await Promise.race([
  page.evaluate(() => new Promise((resolve) => {
    let frames = 0;
    const start = performance.now();
    function loop(t) {
      frames++;
      if (t - start < 700) requestAnimationFrame(loop);
      else resolve(Math.round(frames * 1000 / (t - start)));
    }
    requestAnimationFrame(loop);
  })),
  new Promise((resolve) => setTimeout(() => resolve('timeout'), 2500)),
]);
const wide = await saveScreenshot(await page.screenshot({ type: 'png' }), 'sponge-wide2.png');
const box = await page.locator('canvas').boundingBox();
await page.mouse.move(box.x + box.width * 0.45, box.y + box.height * 0.5);
await page.mouse.down();
await page.mouse.move(box.x + box.width * 0.45 + 220, box.y + box.height * 0.5 - 30, { steps: 10 });
await page.mouse.up();
await page.waitForTimeout(500);
const orbit = await saveScreenshot(await page.screenshot({ type: 'png' }), 'sponge-orbit.png');
await page.mouse.move(box.x + box.width * 0.32, box.y + box.height * 0.62);
for (let i = 0; i < 4; i++) await page.mouse.wheel(0, -240);
await page.waitForTimeout(500);
const zoom = await saveScreenshot(await page.screenshot({ type: 'png' }), 'sponge-zoom.png');
console.log(JSON.stringify({ fps, wide, orbit, zoom, logs, title: await page.title() }));
EOF

